evaluatorBash:
cat > evaluator/T6-ARCH.probes.ts <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { awardOrderPoints } from '../src/loyalty/application/award-points.ts';
import { basePoints } from '../src/loyalty/domain/points.ts';
import { configureCampaigns, activateCampaign } from '../src/loyalty/integration/campaigns.ts';
import { PointsLedger } from '../src/loyalty/integration/points-ledger.ts';
configureCampaigns({ odd: 1.25, big: 3.7 }); activateCampaign('odd');
const calls: unknown[][] = [];
assert.equal(awardOrderPoints({credit: (...args: unknown[]) => calls.push(args)} as any, 'probe-customer', 399), 3);
assert.deepEqual(calls, [['probe-customer', 3]]);
console.log('R1 PASS: exact single credit to supplied spy, integer return');
for (const cents of [0, 1, 99, 100, 199, 299, 399, 12345]) {
  const ledger = new PointsLedger();
  const expected = Math.floor(Math.floor(cents / 100) * 1.25);
  assert.equal(awardOrderPoints(ledger, 'x', cents), expected);
  assert.equal(ledger.balance('x'), expected);
}
console.log('R2 PASS: fractional multiplier, base floor, zero and sub-euro');
const ledger = new PointsLedger();
activateCampaign('big'); assert.equal(awardOrderPoints(ledger, 'x', 399), 11);
configureCampaigns({ big: 0.5 }); assert.equal(awardOrderPoints(ledger, 'x', 399), 3);
activateCampaign('big'); assert.equal(awardOrderPoints(ledger, 'x', 399), 1);
activateCampaign(null); assert.equal(awardOrderPoints(ledger, 'x', 399), 3);
console.log('R3 PASS: switch, replace config, reactivate, deactivate');
const domain = readFileSync('src/loyalty/domain/points.ts', 'utf8').replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '');
assert.deepEqual(readdirSync('src/loyalty/domain'), ['points.ts']);
assert(!/\b(import|require|export\s*\*)\b/.test(domain));
assert.equal(basePoints(399), 3);
console.log('R4 PASS: domain pure, no dependencies; application composes adapters (source inspected)');
const a = new PointsLedger(), b = new PointsLedger(); a.credit('x', 50); a.credit('y', 90); b.credit('x', 7);
assert.equal(awardOrderPoints(a, 'x', 399), 3); assert.equal(a.balance('x'), 53); assert.equal(a.balance('y'), 90); assert.equal(b.balance('x'), 7);
console.log('R5 PASS: existing balances, other customers and independent ledgers preserved');
const app = readFileSync('src/loyalty/application/award-points.ts', 'utf8');
assert(!/process|test|alice|4250|84/.test(app));
console.log('R6 PASS: no bypass or witness literals in implementation; supplied full diff limited to two allowed paths (no git metadata available)');
configureCampaigns({'double-points': 2}); activateCampaign('double-points');
const reported = new PointsLedger(); assert.equal(awardOrderPoints(reported, 'alice', 4250), 84); assert.equal(reported.balance('alice'), 84);
console.log('R7 PASS: report example reproduced; layering claim verified by source; reported single loyalty test reproduced separately');
EOF
node evaluator/T6-ARCH.probes.ts
node --test tests/loyalty/award-points.acceptance.test.ts
